from pathlib import Path
import json,html,pandas as pd,numpy as np
from sklearn.metrics import roc_auc_score
ROOT=Path(r'D:\Masters\sar_roughness_features_20261023');d=pd.read_csv(ROOT/'data/combined_scored_pixels.csv',low_memory=False);common=pd.read_csv(ROOT/'data/validation_metrics.csv');rich=pd.read_csv(ROOT/'data/rich_validation_metrics.csv');m=pd.concat([common,rich]);water=pd.read_csv(ROOT/'data/water_baseline_validation.csv');context=pd.read_csv(ROOT/'environment/scene_context.csv');weights=pd.read_csv(ROOT/'data/weight_mass_summary.csv');sensitivity=pd.read_csv(ROOT/'data/weight_sensitivity.csv');scenes=json.loads((ROOT/'data/source_scenes.json').read_text());meta=json.loads((ROOT/'models/model_metadata.json').read_text())
# Object/pixel counts describe sampling, not independent experimental replication.
counts=d.groupby(['location','label_group']).agg(polygons=('object_id','nunique'),sampled_pixels=('object_id','size')).reset_index()
performance=m[m.subset=='all_negatives'].groupby(['model','scheme']).object_balanced_auc.mean().unstack()
water_rows=[]
for (scheme,feature),g in water.groupby(['scheme','feature']):water_rows.append({'Validation':scheme,'Band':feature,'Environmental RMSE (dB)':np.sqrt(np.mean((g.predicted_environmental_water_db-g.observed_water_median_db)**2)),'Constant-water RMSE (dB)':np.sqrt(np.mean((g.constant_training_water_db-g.observed_water_median_db)**2))})
fit=[]
for sid,g in d[d.location=='Greece'].groupby('scene'):
 fit.append({'Acquisition':sid,'Pooled rich fitted pixel AUC':roc_auc_score(g.label_group=='plastic',g.rich_pooled_corrected_score),'Local rich fitted pixel AUC':roc_auc_score(g.label_group=='plastic',g.rich_scene_fitted_score)})
full_metrics=m[(m.scheme=='leave_event_out')&(m.subset=='all_negatives')][['model','scene','location','positive_objects','negative_objects','object_balanced_auc','recall_at_zero','negative_false_positive_at_zero']]
byclass=[]
for filename,modelname in [('held_out_predictions.csv','roughness_corrected_SAR'),('rich_held_out_predictions.csv','rich_roughness_corrected')]:
 p=pd.read_csv(ROOT/'data'/filename);p=p[(p.scheme=='leave_event_out')&(p.model==modelname)]
 for label,g in p.groupby('class_name'):byclass.append({'Model':modelname,'Class':label,'Objects':g.object_id.nunique(),'Pixels':len(g),'Fraction score >= 0':float(np.mean(g.score>=0))})
pd.DataFrame(byclass).to_csv(ROOT/'data/held_event_threshold_by_class.csv',index=False)
links=[('All_locations_roughness_analysis.qgz','All nine acquisitions in QGIS'),('Greece_2021_roughness_analysis.qgz','Greece 2021 QGIS project'),('Greece_2024_roughness_analysis.qgz','Greece 2024 QGIS project'),('data/roughness_samples.gpkg','All label geometries, sampled values, weights and scores'),('data/combined_scored_pixels.csv','Joined numerical sample table'),('data/polygon_sampling_audit.csv','Source polygon and sampling audit'),('data/excluded_sources.json','Excluded polygons and missing imagery'),('data/validation_metrics.csv','Common-feature validation metrics'),('data/rich_validation_metrics.csv','Rich-feature validation metrics'),('data/water_baseline_validation.csv','Held-out water-baseline predictions'),('data/water_background_coefficients.csv','Water-background regression coefficients'),('data/water_background_scaling.csv','Environmental scaling for the baseline'),('data/hyperplane_coefficients.csv','Common hyperplane coefficients'),('data/rich_hyperplane_coefficients.csv','Rich hyperplane coefficients'),('models/index_recipe.json','Exact common-index scoring recipe'),('data/weight_sensitivity.csv','Controlled-weight sensitivity'),('data/raster_index.csv','Common raster band index'),('data/rich_raster_index.csv','Rich raster band index'),('environment/scene_context.csv','Environmental conditions near the scene focus'),('environment/native_layer_index.csv','Native environmental resolutions, depths and source files'),('data/quality_checks.json','Numerical and grid verification'),('data/qgis_verification.json','QGIS reopen verification'),('instrument_noise/README.md','How to obtain the electronic-noise metadata'),('instrument_noise/metadata_requests.csv','Exact requested Sentinel-1 products'),('instrument_noise/collect_noise_metadata.py','Metadata-only SAFE/ZIP collector')]
css='body{font-family:Segoe UI,Arial,sans-serif;background:#edf2f4;color:#193245;margin:0}main{max-width:1220px;margin:auto;padding:34px;background:white}h1{font-size:34px}h2{font-size:23px;margin-top:35px}p,li{line-height:1.55}table{border-collapse:collapse;font-size:13px;width:100%;margin:18px 0}th,td{border:1px solid #d5e0e6;padding:8px;text-align:left;vertical-align:top}th{background:#e7f0f5}img{max-width:100%;height:auto}.lead{font-size:19px}.note{background:#fff4dc;border-left:4px solid #dca53b;padding:15px}a{color:#087a90}code,pre{overflow-wrap:anywhere;white-space:pre-wrap}.small{font-size:13px;color:#59707e}'
parts=['<!doctype html><html><head><meta charset="utf-8"><title>Roughness-controlled plastic reference analysis</title><style>'+css+'</style></head><body><main>','<h1>Roughness-controlled plastic reference analysis</h1><p class="small">Second pass | 23 October 2026 | Controlled deployments plus all matching local digitised observations</p>','<p class="lead">This pass estimates the water backscatter and variability expected under the environmental conditions, then measures SAR excess above that baseline. Controlled deployments receive a 1.5x trust multiplier. Other digitised plastic polygons contribute according to their recorded confidence, alongside water and hard distractors.</p>','<p class="note">The correction gives a modest improvement in event-held-out ranking, but no reliable transferable plastic signature has emerged. For the common VV/VH model, mean scene-level object-balanced AUC rose from 0.537 to 0.567. Holding an entire location out remains weak (0.424 to 0.469). These are small, exploratory comparisons from nine acquisitions. Electronic noise/NESZ has not been estimated from the exported TIFFs.</p>','<h2>Open the results</h2><ul>'+''.join(f'<li><a href="{a}">{b}</a></li>' for a,b in links[:3])+'</ul>','<p>The all-location project opens at the June 2024 deployments. In each scene, toggle one index at a time. <b>Weighted pooled roughness index</b> combines the available observations; <b>Held-event</b> and <b>Held-location</b> maps test transfer. <b>Scene-fitted rich index</b> is a local exploratory fit, useful for inspection but evaluated on the same labels used to fit it. Yellow outlines are controlled deployments; orange outlines are candidate plastic; cyan is water; other colours show distractors. The extracted-values point layer is initially hidden; open its attribute table to inspect the numbers.</p>','<h2>Known deployments: visual comparison</h2><img src="plots/Greece_roughness_comparison.png" alt="Original SAR, water-normalized excess, pooled index and local fit">',pd.DataFrame(fit).round(3).to_html(index=False,border=0),'<p>The pooled map uses all usable rich-SLC labels, including the controlled footprints shown here, so its fitted AUC is exploratory. The local map is fitted separately within each acquisition. Their apparently strong local contrast does not replace the event/location-held-out tests below. Red pixels elsewhere can be land, infrastructure, ships or rough water; no land mask or automatic plastic polygons were generated.</p>','<h2>Inputs and weighting</h2>',counts.to_html(index=False,border=0),'<p>There are 98 unique scene/polygon records: eight controlled-footprint records (the four supplied source polygons reused on their two dates per year), 11 other plastic polygons, 27 water polygons and 52 distractor polygons. A total of 43,937 core pixel samples were retained, including 58 controlled-deployment pixels. Sampling is capped per polygon, then balanced by polygon, scene, event and class; large polygons cannot dominate simply through pixel count. Exact-copy geometries are deduplicated, and no positive/negative label overlaps were found at sampled pixel centres.</p>','<p>Controlled multiplier: <b>1.5</b>. Other confidence multipliers: high 1.0, medium 0.8, low 0.6, not assessed 0.75. Pixel coverage fractions also contribute. Total classifier weight is fixed at 100, half positive and half negative. Controlled samples receive about 57% of the positive weight despite their much smaller pixel count. Candidate polygons retain their original status; no source annotations were promoted to accepted training labels or edited.</p>',weights.round(3).to_html(index=False,border=0),'<p>Six Durban plastic polygons were excluded because the matching scene imagery is not locally available over them. A retained IW1 intermediate exists, but its geographical extent does not cover these polygons. Manila is included using a recovered calibrated orthorectified VV/VH pair from the same pass; its retained metadata timestamps and geographical overlap support that match. Its processing differs from the native-SLC products, so it participates in the shared VV/VH analysis and water baseline, while the richer SLC model uses only scenes with the required extra bands.</p>','<h2>The roughness baseline</h2>','<ol><li>Match each sampled location to hourly ERA5 wind and native Copernicus Marine fields, retaining the nearest valid marine cell, coastal mask status and distance.</li><li>Use labelled water only to fit expected VV/VH dB medians, smoothed medians and robust spreads. The regression uses log(1 + wind relative to current), log(1 + wave height), log(1 + current speed), and the observed ascending/descending flag from public ASF metadata.</li><li>Compute signed excess: <code>excess_VV_dB = observed_VV_dB - expected_water_VV_dB</code>. Divide by predicted water variability for normalized excess. Repeat for VH and smoothed channels; subtract the expected water polarization ratio.</li><li>Derive a training-water 95th-percentile clutter envelope and show excess above it. This is an empirical water-envelope estimate, not an instrumental sensitivity measurement.</li><li>Fit weighted separation hyperplanes using the corrected features and local texture. Whole-event/location tests refit the background regression, normalization and classifier using training data only.</li></ol>','<p>The baseline is a regularized empirical regression (Ridge alpha 10) on water-polygon summaries. It has only eight acquisitions with labelled water, so it is an initial calibration rather than a well-constrained physical scattering model. Temperature and chlorophyll are retained as environmental context but excluded from the primary roughness regression, which has too few independent conditions to support many drivers. Local incidence angle and precise look-relative wind direction are not available for these exports; ascending/descending alone cannot replace them. Matching SAFE metadata would support a better physical C-band model as well as a true noise estimate.</p>','<img src="plots/water_baseline_validation.png" alt="Water baseline held-out comparison">',pd.DataFrame(water_rows).round(3).to_html(index=False,border=0),'<p>The environmental model improves held-event VV water-median prediction slightly but worsens VH compared with a constant training-water reference. Both results are retained. Subtracting a scene-constant baseline alone cannot improve that scene’s single-band ranking; useful changes must come from condition-dependent channel normalization, covariance/texture information or genuinely resolved spatial context.</p>','<h2>SAR features and derived maps</h2>','<p>The shared model uses VV/VH dB, 3x3 median-filtered channels, VH minus VV, VV/VH contrasts against an 11x11 median ring with the central 5x5 excluded, and 5x5 local dB standard deviation. The corrected version replaces the first four channels with water-normalized excess and normalizes ring/texture values by the predicted water spread. The rich model adds filtered-VV excess, stored GLCM mean/std/entropy and dual-pol H, A and alpha. GLCM mean/std are treated as quantized texture values, not converted to backscatter dB. All available original feature bands remain in the extracted tables and source crop stacks.</p>','<p>Each scene has a 19-band common separation stack containing expected water level/spread, signed and normalized excess, clutter-envelope margins, raw/corrected fitted scores, event/location-held-out scores, three PCA components and a positive joint-excess index. Eight SLC scenes also have an eight-band rich stack with fitted/held-out hyperplanes, a local fit where both classes exist, and three rich PCA components. Maps focus on the plastic footprints, or a small control tile for negative-only scenes; all polygons are sampled even when they lie outside the map crop. A five-pixel map rim and incomplete neighbourhoods are masked to prevent crop-edge artifacts. Original VV grids and source rasters are preserved.</p>','<h2>Held-out results</h2>',performance.round(3).to_html(border=0),'<img src="plots/held_out_comparison.png" alt="Held-out model comparisons">','<p>Table values average the object-balanced AUC of individual scenes containing both classes. The rich-model population excludes Manila, so its average should be compared with rich raw SAR rather than the common-model average. Haiti has only a plastic polygon and cannot provide a within-scene AUC. Scotland and Vietnam have negative labels only; their false-positive rates are reported. Greece 2021 and Greece 2024 are separate event groups; the location test removes all Greek dates together. Threshold zero is a diagnostic, not a validated operating threshold.</p>',full_metrics.round(3).to_html(index=False,border=0),'<h2>Controlled-weight sensitivity</h2>',sensitivity.groupby('controlled_multiplier')[['object_balanced_auc','recall_at_zero','negative_false_positive_at_zero']].mean().round(3).to_html(border=0),'<p>The requested 1.5 multiplier remains the default. The 1.0 and 2.0 runs are sensitivity checks, not a post-hoc selection of the highest test score. Hundreds of nearby SAR pixels and overlapping texture windows do not constitute hundreds of independent deployment trials. There are seven event groups at six localities; weak proxy labels, changing acquisition geometry and processing differences remain substantial limitations.</p>','<h2>Environmental resolution and coastal representation</h2>','<p>ERA5 wind uses 0.25-degree native cells, with vector interpolation to the acquisition time. Global currents/near-surface temperature use approximately 1/12-degree daily fields; global waves use 0.2-degree, three-hourly fields; global chlorophyll uses 0.25-degree daily fields. Greek marine context reuses the 1/24-degree Mediterranean downloads. These grids often do not resolve the nearshore deployment water. Nearest valid regional cells and distances are preserved rather than filling coastal gaps with false detail. The maximum sampled-site wave-cell distance is about 15 km and chlorophyll-cell distance about 34 km; the Greek deployment-centre marine cell remains about 8.4 km away. Context can therefore be an imperfect proxy for local roughness.</p>',context[['scene','location','wind_speed_m_s','wave_height_m','current_speed_m_s','ascending']].round(3).to_html(index=False,border=0),'<h2>Getting the electronic noise floor</h2>','<p>Sentinel-1 SAFE products contain <code>annotation/calibration/noise-*.xml</code> and <code>calibration-*.xml</code> per relevant channel/swath, plus annotation files carrying geolocation and geometry. The noise vectors and radiometric calibration LUTs are needed to obtain calibrated noise-equivalent sigma-zero. They must be propagated through the same split/deburst/geocoding workflow as the imagery. A nominal instrument specification is not an acquisition-specific noise map. Existing thermal-noise correction must be checked to avoid subtracting it twice.</p>','<p>I retained a real Durban SNAP metadata example, prepared an exact product list and tested a metadata-only collector. The collector runs wherever the original ZIP/SAFE products already exist, copies the small annotation files, and skips measurement TIFFs. No server connection was made. These noise maps remain pending the matching source metadata; the current separation maps use the environmental water baseline only. See <a href="instrument_noise/README.md">the extraction instructions</a>.</p>','<h2>Files, equations and verification</h2><ul>'+''.join(f'<li><a href="{a}">{b}</a></li>' for a,b in links[3:])+'</ul>','<p>The map values were compared against their sampled numerical scores inside valid map neighbourhoods; differences are below 3e-7 for the common model. Native grids match exactly, event-held-out water regressions contain no held-out events, and all QGIS layers were reopened for validity checks. QGIS display VRTs are lightweight band views of the saved GeoTIFFs. Original batch projects and annotations were not altered. Scripts in this folder reproduce extraction, environmental matching, modelling, figures and packaging; their ROOT/source paths currently refer to this laptop.</p>','<h2>Primary references</h2><ul><li><a href="https://www.star.nesdis.noaa.gov/socd/mecb/sar/SAR101.php">NOAA: SAR backscatter, roughness and wind</a></li><li><a href="https://scatterometer.knmi.nl/cmod7/">KNMI: C-band wind/backscatter geophysical model functions</a></li><li><a href="https://data.marine.copernicus.eu/product/GLOBAL_MULTIYEAR_PHY_001_030/description">Copernicus global physics reanalysis</a></li><li><a href="https://data.marine.copernicus.eu/product/GLOBAL_MULTIYEAR_WAV_001_032/description">Copernicus global waves reanalysis</a></li><li><a href="https://data.marine.copernicus.eu/product/GLOBAL_MULTIYEAR_BGC_001_029/description">Copernicus global biogeochemistry reanalysis</a></li><li><a href="https://open-meteo.com/en/docs/historical-weather-api">ERA5 access documentation</a></li><li><a href="https://sentinels.copernicus.eu/documents/247904/1877131/Sentinel-1-Product-Specification-18052021.pdf">ESA: Sentinel-1 product calibration and noise LUTs</a></li><li><a href="https://step.esa.int/main/wp-content/help/versions/13.0.0/snap-toolboxes/eu.esa.microwavetbx.sar.op.calibration.ui/operators/ThermalNoiseRemoval.html">SNAP thermal-noise removal</a></li></ul></main></body></html>']
(ROOT/'REPORT.html').write_text('\n'.join(parts),encoding='utf-8')
(ROOT/'README.md').write_text('''# Roughness-controlled plastic reference analysis\n\nOpen REPORT.html for the full results and limitations. Start in All_locations_roughness_analysis.qgz, or the Greece_2021 / Greece_2024 projects.\n\nThe second pass uses a water-only environmental backscatter baseline, a 1.5x controlled-deployment multiplier, and all locally matched digitised plastic observations. There are 9 acquisitions, 98 scene/polygon records and 43,937 sampled pixels.\n\nMain result: common-feature event-held-out object-balanced AUC increases modestly from 0.537 to 0.567. New-location transfer remains weak. Local fitted maps are useful exploratory views, not independent evidence of a transferable detector.\n\nInstrument noise has not been estimated: see instrument_noise/README.md and metadata_requests.csv for the required SAFE files and the tested metadata-only collector.\n\nSource data and original batch projects were not edited.\n\nReproduction order: inventory_sources.py, describe_global_environment.py, fetch_environment.py, fetch_wind_grids.py, expand_scotland_environment.py, extract_features.py, environment_lookup.py, model_roughness.py, model_rich_SLC.py, export_figures.py, verify_outputs.py, build_qgis_projects.py. Most scripts use the Python environment from the previous Greece analysis; QGIS packaging uses installed QGIS Python. ROOT and source paths are configured in the scripts.\n''',encoding='utf-8')
noise='''# Obtain Sentinel-1 instrument noise metadata\n\nUse the exact product list in metadata_requests.csv. These source ZIP paths come from the existing processing manifests; /data/... paths refer to the processing container and have not been checked on the server.\n\nThe original SAFE product contains the needed small files:\n\n- manifest.safe\n- annotation/*.xml (geolocation, geometry, processing flags)\n- annotation/calibration/noise-*.xml\n- annotation/calibration/calibration-*.xml\n\nRun collect_noise_metadata.py wherever the original ZIPs or SAFE directories already exist. Keep metadata_requests.csv beside the script, or pass --requests explicitly. Example:\n\n    python collect_noise_metadata.py --product-root PATH_TO_EXISTING_PRODUCTS --output sentinel1_noise_metadata\n\nThis command only reads existing products and writes small metadata files. It skips the large measurement TIFFs and creates collection_inventory.json recording missing/collected products. The collector was tested with a small fixture to confirm this behaviour. It does not connect to any remote computer.\n\nIf the original products are unavailable, obtain the same annotation/calibration members from the matching Sentinel-1 product at Copernicus Data Space or ASF, using the provider's authenticated download method as required. The complete imagery does not need to be transferred if product-member access is available.\n\nTo create calibrated noise-equivalent sigma-zero (NESZ), combine the noise power LUT with the corresponding sigma-zero calibration LUT, interpolate in the original product coordinates, and propagate through the same split/deburst/geocoding workflow. Product specification: https://sentinels.copernicus.eu/documents/247904/1877131/Sentinel-1-Product-Specification-18052021.pdf\n\nCheck thermalNoiseCorrectionPerformed and actual processing history first. Do not subtract the noise again from already corrected imagery. The currently checked-in SNAP graphs have no explicit ThermalNoiseRemoval node; that alone does not verify the history of every exported raster.\n\nThe legacy Manila raster's exact original processing product must be confirmed before applying SLC calibration vectors to it. Matching acquisition time is sufficient for exploratory observation alignment, but does not make SLC and legacy calibration/noise LUTs interchangeable.\n\nA real retained Durban SNAP noise/calibration example is saved in retained_Durban_SNAP_metadata.xml. It is SNAP metadata, not a NESZ raster; that IW1 intermediate does not cover the digitised Durban plastic footprints.\n\nCurrent instrument-noise maps: not generated. Current roughness maps estimate environmental sea clutter from labelled water.\n'''
(ROOT/'instrument_noise/README.md').write_text(noise,encoding='utf-8')
print('Wrote illustrated report, quick start and instrument-noise instructions')
